import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("vendor audit trail", () => {
  test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Audit Vendor"),
        category: "software",
        contact_email: `audit-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@northwind-vendors.com`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = await created.json();

    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample("w9.txt")),
        },
      },
    });
    expect(upload.status(), await upload.text()).toBe(201);

    // Act: extraction runs in the background, so poll until its event is recorded.
    let items: Array<{ action: string; actor: { email: string }; at: string }> = [];
    await expect
      .poll(
        async () => {
          const res = await member.get(`/api/vendors/${vendor.id}/audit`);
          expect(res.status(), await res.text()).toBe(200);
          items = ((await res.json()) as { items: typeof items }).items;
          return items.map((e) => e.action);
        },
        { timeout: 30_000 },
      )
      .toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

    // Assert
    expect(items.map((e) => e.action)).toEqual([
      "vendor.created",
      "document.uploaded",
      "document.extracted",
    ]);
    for (const event of items) {
      expect(event.actor.email).toBe("member@northwind.test");
      expect(event.at, JSON.stringify(event)).toBeTruthy();
      expect(Number.isNaN(Date.parse(event.at)), event.at).toBe(false);
    }
  });
});
